mapper.select:
SELECT o.oppt_id,o.oppt_no,o.oppt_nm,c.ptnr_nm AS customer,b.bsn_part_nm AS part,
    o.bsn_stg_cd,o.win_prblt_rt,o.expc_amt,o.cntrct_ty_cd,o.expc_bgn_ym AS bgn_ym,o.expc_mnth_qty AS mth_cnt,
    o.next_work_desc AS next_action,o.next_work_ddln_dt AS next_action_dt,o.oppt_stts_cd,o.quot_aprv_stts_cd AS approval_state,o.win_prj_id,p.prj_no AS project,
    coalesce((SELECT sum(n.psn_cnt) FROM bsn.oppt_need n WHERE n.oppt_id=o.oppt_id AND n.use_yn='Y'),0) AS needed_people,
    coalesce(o.updated_at,o.created_at) AS last_update
    FROM bsn.oppt o JOIN mst.ptnr c ON c.ptnr_id=o.cust_ptnr_id LEFT JOIN mst.bsn_part b ON b.bsn_part_id=o.bsn_part_id LEFT JOIN prj.prj p ON p.prj_id=o.win_prj_id
    WHERE o.oppt_stts_cd=#{status}
    AND (strpos(lower(o.oppt_nm),lower(#{q}))>0 OR strpos(lower(c.ptnr_nm),lower(#{q}))>0)
    AND o.bsn_stg_cd=#{stage}AND o.cust_ptnr_id=#{customer}
    AND o.bsn_part_id=#{part}
    AND to_char(to_date(o.expc_bgn_ym,'YYYY-MM')+(o.expc_mnth_qty-1)*interval '1 month','YYYY-MM') >= #{from}
    AND o.expc_bgn_ym<=#{to}
    ORDER BY o.oppt_id
